#!/usr/bin/env bash
# sign-release.sh — Stub: cosign signing instructions for the 4 PodMotion images.
#
# PodMotion targets SLSA Build Level 2 (L2) provenance, generated via the
# slsa-framework/slsa-github-generator reusable workflow in GitHub Actions.
# Signing is performed in CI automatically on release tags; this script documents
# the equivalent manual steps for local signing when CI signing is unavailable.
#
# SLSA L2 requirements:
#   - Build runs on a hosted, ephemeral runner (not self-hosted)
#   - Provenance is generated by the SLSA GitHub generator, not by the repo workflow
#   - The .intoto.jsonl attestation is uploaded to the release assets
#   - Images are signed with a Sigstore/Rekor-anchored cosign keyless signature
#     OR with a long-lived key whose public half is published in KEYS.md
#
# Prerequisites (local):
#   brew install cosign
#   cosign version  # must be >= 2.0
#
# For GitHub Actions, see .github/workflows/release.yml — the release job calls:
#   uses: slsa-framework/slsa-github-generator/.github/workflows/builder_container_slsa3.yml@v2
#
# ---
# IMAGE REGISTRY AND TAGS
# Set VERSION to the release tag before running, e.g.:
#   VERSION=v0.2.0 bash scripts/sign-release.sh
# ---

set -euo pipefail

VERSION="${VERSION:-}"
if [ -z "${VERSION}" ]; then
  echo "ERROR: VERSION must be set (e.g. VERSION=v0.2.0 bash scripts/sign-release.sh)"
  exit 1
fi

REGISTRY="ghcr.io/podmotion-io"

IMAGES=(
  "${REGISTRY}/operator:${VERSION}"
  "${REGISTRY}/agent:${VERSION}"
  "${REGISTRY}/scheduler:${VERSION}"
  "${REGISTRY}/kind-node:${VERSION}"
)

KEY="${COSIGN_KEY:-}"  # path to cosign private key, or empty for keyless

echo "==> PodMotion release signing stub (VERSION=${VERSION})"
echo ""
echo "The following cosign commands would sign the 4 PodMotion images."
echo "This script is a STUB — review and adapt before running in production."
echo ""

for image in "${IMAGES[@]}"; do
  echo "--- Image: ${image}"
  if [ -n "${KEY}" ]; then
    echo "  cosign sign --key \"${KEY}\" \"${image}\""
  else
    echo "  # Keyless signing (requires OIDC provider, e.g. GitHub Actions OIDC):"
    echo "  cosign sign \"${image}\""
    echo "  # or with explicit key:"
    echo "  cosign sign --key <path-to-cosign.key> \"${image}\""
  fi
  echo ""
done

echo "==> To verify a signed image after release:"
echo "  cosign verify \\"
echo "    --certificate-identity-regexp 'https://github.com/podmotion-io/podmotion/.github/workflows/release.yml.*' \\"
echo "    --certificate-oidc-issuer 'https://token.actions.githubusercontent.com' \\"
echo "    ${REGISTRY}/operator:${VERSION}"
echo ""
echo "==> SLSA L2 provenance verification:"
echo "  slsa-verifier verify-image \\"
echo "    --source-uri github.com/podmotion-io/podmotion \\"
echo "    --source-tag ${VERSION} \\"
echo "    ${REGISTRY}/operator:${VERSION}"
echo ""
echo "NOTE: In GitHub Actions CI, signing happens automatically in the release"
echo "      workflow via the slsa-framework/slsa-github-generator step."
echo "      Do NOT run this script from a developer workstation for official"
echo "      releases — use the CI signing job to ensure provenance chain of custody."
